<?php
require_once __DIR__.'/includes/auth.php';
require_once __DIR__.'/includes/ai_service.php';
require_once __DIR__.'/includes/ai_document_templates.php';
require_module('trolyai', 'view');
$user = current_user() ?? [];
$isAdmin = ($user['role'] ?? '') === 'admin';
$catalog = cds_ai_assistants();
$available = array_filter($catalog, fn($item)=>$isAdmin || can_perm($item['permission']));
if (empty($_SESSION['ai_csrf'])) $_SESSION['ai_csrf'] = bin2hex(random_bytes(24));
$csrf = (string)$_SESSION['ai_csrf'];
$selected = trim((string)($_GET['assistant'] ?? ''));
if (!isset($available[$selected])) $selected = array_key_first($available) ?? '';

if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'save_settings') {
    if (!$isAdmin || !hash_equals($csrf, (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Không có quyền thực hiện.'); }
    if (cds_ai_save_settings($_POST)) flash('Đã lưu nhà cung cấp, API key và mô hình AI.', 'success');
    else flash('Không lưu được cấu hình ngoài web root. Hãy kiểm tra quyền ghi thư mục cds_private.', 'danger');
    header('Location: '.BASE_URL.'trolyai.php?settings=1'); exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='upload_template'){
    if(!$isAdmin||!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Không có quyền thực hiện.');}
    $res=cds_ai_template_upload($_FILES['template_file']??[],trim((string)($_POST['template_type']??'')),trim((string)($_POST['template_name']??'')),$user);
    flash(!empty($res['ok'])?'Đã thêm mẫu văn bản.':($res['message']??'Không thêm được mẫu.'),!empty($res['ok'])?'success':'danger');
    header('Location: '.BASE_URL.'trolyai.php?templates=1');exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='delete_template'){
    if(!$isAdmin||!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Không có quyền thực hiện.');}
    $ok=cds_ai_template_delete(trim((string)($_POST['template_id']??'')));flash($ok?'Đã xóa mẫu văn bản.':'Không xóa được mẫu.',$ok?'success':'danger');
    header('Location: '.BASE_URL.'trolyai.php?templates=1');exit;
}
$settings = cds_ai_settings();
$providers = cds_ai_provider_catalog();
$showSettings = $isAdmin && isset($_GET['settings']);
$showTemplates=$isAdmin&&isset($_GET['templates']);
$documentTemplates=cds_ai_template_all();
$templateTypes=cds_ai_template_types();
